# ---------- I1 |a-b| ----------
from functools import lru_cache
@lru_cache(None)
def fin(state):
    if len(state)==1: return {state[0]:()}
    res={};s=list(state);seen=set()
    for a_i in range(len(s)):
        for b_i in range(a_i+1,len(s)):
            a,b=s[a_i],s[b_i]
            if (a,b) in seen: continue
            seen.add((a,b))
            rest=s[:a_i]+s[a_i+1:b_i]+s[b_i+1:]+[abs(a-b)]
            for v,path in fin(tuple(sorted(rest))).items():
                if v not in res: res[v]=((a,b),)+path
    return res
r=fin(tuple(range(1,11)));assert sorted(r)==[1,3,5,7,9]
def trace(path):
    st=list(range(1,11));out=[]
    for a,b in path:
        st.remove(a);st.remove(b);st.append(abs(a-b));out.append(f'({a}, {b}) → {abs(a-b)}')
    assert st==[abs(path[-1][0]-path[-1][1])]
    return ', '.join(out)
t9=trace(r[9]);t1=trace(r[1])
