def bfs(n,kk):
    masks=[((1<<kk)-1)<<j for j in range(n-kk+1)]
    d={0:0};qq=deque([0])
    while qq:
        s_=qq.popleft()
        for m in masks:
            t=s_^m
            if t not in d:d[t]=d[s_]+1;qq.append(t)
    return d.get((1<<n)-1)
assert bfs(6,2)==3 and bfs(7,2) is None and bfs(6,3)==2 and bfs(7,3) is None and bfs(8,3) is None and bfs(9,3)==3
