# ---------- S1 계단 성냥 ----------
def M(n):
    cells={(a,b) for a in range(n) for b in range(n) if a+b<n};edges=set()
    for (a,b) in cells:edges|={('h',a,b),('h',a+1,b),('v',a,b),('v',a,b+1)}
    return len(edges)
assert [M(n) for n in range(1,5)]==[4,10,18,28] and all(M(n)==n*(n+3) for n in range(1,30)) and max(n for n in range(1,30) if n*(n+3)<=100)==8 and max(n for n in range(1,30) if n*(n+3)<=200)==12
def stair(n):
    cells=[(a,b) for a in range(n) for b in range(n) if a+b<n]
    sc2=14;w=n*sc2+8
    rects=''.join(f'<rect x="{4+b*sc2}" y="{4+(n-1-a)*sc2}" width="{sc2}" height="{sc2}" fill="none" stroke="currentColor" stroke-width="1.6"/>' for a,b in cells)
    return f'<svg viewBox="0 0 {w} {w}" width="{w+6}" role="img" aria-label="{n}단계 계단 모양">{rects}</svg>'
figS=('<div class="fig"><div style="display:flex;gap:18px;justify-content:center;align-items:flex-end;flex-wrap:wrap">'
 +''.join(f'<div>{stair(n)}<div>{n}단계</div></div>' for n in (1,2,3))+'</div></div>')
